"use client";

import {
  useEffect,
  useRef,
  useState,
  HTMLAttributes,
  useCallback,
} from "react";
import { cn } from "@/lib/utils";

const W = 380;
const H = 360;
const CW = 210;
const CH = 260;
const STEP_X = 28;
const STEP_Y = 20;
const STEP_Z = 55;

export interface Card {
  id: string;
  title: string;
  subtitle?: string;
  src: string;
}

const DEFAULT_CARDS: Card[] = [
  {
    id: "mount",
    title: "Alpine Serenity",
    subtitle: "Switzerland",
    src: "https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=600&q=80",
  },
  {
    id: "bloom",
    title: "Floral Whisper",
    subtitle: "Japan",
    src: "https://images.unsplash.com/photo-1490750967868-88aa4486c946?w=600&q=80",
  },
  {
    id: "peak",
    title: "Midnight Summit",
    subtitle: "Norway",
    src: "https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=600&q=80",
  },
  {
    id: "wings",
    title: "Verdant Canopy",
    subtitle: "Amazonia",
    src: "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=600&q=80",
  },
];

export interface CardSwapProps extends HTMLAttributes<HTMLDivElement> {
  items?: Card[];
  auto?: boolean;
  every?: number;
  showIndicators?: boolean;
}

export function CardSwap({
  items = DEFAULT_CARDS,
  auto = false,
  every = 4.5,
  showIndicators = true,
  className,
  ...props
}: CardSwapProps) {
  const [order, setOrder] = useState<string[]>(items.map((c) => c.id));
  const [isSwapping, setIsSwapping] = useState(false);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const els = useRef<Record<string, HTMLDivElement | null>>({});

  const stateRef = useRef({
    hover: false,
    drag: null as null | {
      id: string;
      pid: number;
      startX: number;
      startY: number;
      dx: number;
      dy: number;
      t: number;
    },
  });

  const getSlotTransform = (k: number) => {
    const x = k * STEP_X;
    const y = -k * STEP_Y;
    const z = -k * STEP_Z;
    return `translate3d(${x}px, ${y}px, ${z}px) rotateZ(${k * -1.5}deg) skewY(${Math.max(0, 4 - k)}deg)`;
  };

  const settle = useCallback(() => {
    for (const el of Object.values(els.current)) {
      if (el) {
        el.style.transition =
          "transform 0.45s cubic-bezier(0.2, 0.9, 0.3, 1.2), box-shadow 0.45s ease";
        el.style.transform = "";
      }
    }
  }, []);

  const swap = useCallback(
    (direction: "next" | "prev" = "next") => {
      setIsSwapping(true);
      settle();
      setOrder((current) => {
        if (direction === "next") {
          return [...current.slice(1), current[0]];
        }
        return [current[current.length - 1], ...current.slice(0, -1)];
      });
      setTimeout(() => setIsSwapping(false), 450);
    },
    [settle]
  );

  // Pointer drag logic with momentum and dynamic tilt
  const grab = (
    e: React.PointerEvent<HTMLDivElement>,
    id: string,
    isFront: boolean
  ) => {
    if (!isFront || stateRef.current.drag || e.button !== 0) return;

    const target = e.currentTarget;
    target.setPointerCapture(e.pointerId);

    stateRef.current.drag = {
      id,
      pid: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      dx: 0,
      dy: 0,
      t: performance.now(),
    };

    target.style.transition = "none";

    const onPointerMove = (ev: PointerEvent) => {
      const drag = stateRef.current.drag;
      if (!drag || ev.pointerId !== drag.pid) return;

      drag.dx = ev.clientX - drag.startX;
      drag.dy = ev.clientY - drag.startY;

      const rubberX = 220 * Math.tanh(drag.dx / 220);
      const rubberY = 180 * Math.tanh(drag.dy / 180);
      const rotate = rubberX * 0.08;

      target.style.transform = `${getSlotTransform(0)} translate3d(${rubberX.toFixed(1)}px, ${rubberY.toFixed(1)}px, 40px) rotate(${rotate.toFixed(2)}deg)`;
    };

    const onPointerUp = (ev: PointerEvent) => {
      const drag = stateRef.current.drag;
      if (!drag || ev.pointerId !== drag.pid) return;

      const duration = Math.max(1, performance.now() - drag.t);
      const dist = Math.hypot(drag.dx, drag.dy);
      const velocity = dist / duration;
      stateRef.current.drag = null;

      try {
        target.releasePointerCapture(ev.pointerId);
      } catch {}

      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerup", onPointerUp);
      window.removeEventListener("pointercancel", onPointerUp);

      // Trigger condition: quick flick or dragged > 75px
      if (dist > 75 || (velocity > 0.65 && dist > 25)) {
        // Throw away animation before state swap
        target.style.transition =
          "transform 0.35s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.35s ease";
        const throwX = drag.dx > 0 ? 300 : -300;
        target.style.transform = `${getSlotTransform(0)} translate3d(${throwX}px, ${drag.dy * 1.5}px, 0px) rotate(${throwX * 0.1}deg)`;
        target.style.opacity = "0";

        setTimeout(() => {
          target.style.opacity = "";
          swap("next");
        }, 220);
        return;
      }

      settle();
    };

    window.addEventListener("pointermove", onPointerMove);
    window.addEventListener("pointerup", onPointerUp);
    window.addEventListener("pointercancel", onPointerUp);
  };

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!stateRef.current.hover) return;
      if (e.key === "ArrowRight") swap("next");
      if (e.key === "ArrowLeft") swap("prev");
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [swap]);

  // Autoplay
  useEffect(() => {
    if (!auto) return;
    const interval = window.setInterval(
      () => {
        if (
          !stateRef.current.hover &&
          !stateRef.current.drag &&
          !document.hidden &&
          !isSwapping
        ) {
          swap("next");
        }
      },
      Math.max(2, every) * 1000
    );
    return () => window.clearInterval(interval);
  }, [auto, every, swap, isSwapping]);

  return (
    <div
      ref={containerRef}
      tabIndex={0}
      className={cn(
        "relative flex flex-col items-center justify-center select-none outline-none focus-visible:ring-2 focus-visible:ring-sky-500/50 rounded-2xl p-4",
        className
      )}
      style={{ width: W, height: H }}
      onPointerEnter={() => {
        stateRef.current.hover = true;
      }}
      onPointerLeave={() => {
        stateRef.current.hover = false;
      }}
      {...props}
    >
      {/* 3D Perspective Stage */}
      <div
        className="relative"
        style={{
          width: CW,
          height: CH,
          perspective: 1000,
          transformStyle: "preserve-3d",
        }}
      >
        {items.map((card) => {
          const k = order.indexOf(card.id);
          const isFront = k === 0;
          const scale = 1 - k * 0.05;
          const blur = k === 0 ? 0 : Math.min(k * 1.8, 5);
          const brightness = 1 - k * 0.12;

          return (
            <div
              key={card.id}
              ref={(el) => {
                els.current[card.id] = el;
              }}
              data-front={isFront || undefined}
              onPointerDown={(e) => grab(e, card.id, isFront)}
              className={cn(
                "absolute inset-0 rounded-2xl overflow-hidden will-change-transform",
                "bg-zinc-900 border border-white/10 shadow-[0_18px_36px_-8px_rgba(0,0,0,0.5)]",
                isFront
                  ? "cursor-grab active:cursor-grabbing hover:shadow-[0_24px_48px_-10px_rgba(0,0,0,0.7)]"
                  : "pointer-events-none"
              )}
              style={{
                zIndex: items.length - k,
                transform: getSlotTransform(k),
                transformOrigin: "center bottom",
                filter: `blur(${blur}px) brightness(${brightness})`,
                transition:
                  "transform 0.45s cubic-bezier(0.2, 0.9, 0.3, 1.2), filter 0.45s ease, opacity 0.45s ease",
              }}
            >
              {/* Image Layer */}
              <img
                src={card.src}
                alt={card.title}
                draggable={false}
                className="w-full h-full object-cover select-none pointer-events-none transform transition-transform duration-500 hover:scale-105"
              />

              {/* Realistic Vignette Overlay */}
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent pointer-events-none" />

              {/* Dynamic Specular Sheen (Visible on front card) */}
              <div
                className={cn(
                  "absolute inset-0 bg-gradient-to-tr from-white/15 via-transparent to-transparent opacity-0 pointer-events-none transition-opacity duration-300",
                  isFront && "opacity-100"
                )}
              />

              {/* Card Meta / Badge */}
              <div className="absolute bottom-3 left-3 right-3 text-white pointer-events-none">
                <div className="flex items-center justify-between">
                  <div>
                    <h3 className="font-semibold text-sm tracking-wide leading-tight drop-shadow-md">
                      {card.title}
                    </h3>
                    {card.subtitle && (
                      <p className="text-[11px] text-zinc-300/90 font-medium">
                        {card.subtitle}
                      </p>
                    )}
                  </div>
                  {isFront && (
                    <span className="text-[10px] px-2 py-0.5 rounded-full bg-white/20 backdrop-blur-md border border-white/20 font-mono tracking-wider">
                      SWIPE
                    </span>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Interactive Dots Pagination */}
      {showIndicators && (
        <div className="absolute bottom-2 flex items-center gap-1.5 z-20">
          {items.map((c) => {
            const isActive = order[0] === c.id;
            return (
              <button
                key={c.id}
                type="button"
                onClick={() => {
                  const targetIdx = order.indexOf(c.id);
                  if (targetIdx > 0) {
                    setOrder((curr) => [
                      ...curr.slice(targetIdx),
                      ...curr.slice(0, targetIdx),
                    ]);
                  }
                }}
                className={cn(
                  "h-1.5 rounded-full transition-all duration-300",
                  isActive
                    ? "w-6 bg-white shadow-sm"
                    : "w-1.5 bg-white/30 hover:bg-white/60"
                )}
                aria-label={`Jump to ${c.title}`}
              />
            );
          })}
        </div>
      )}
    </div>
  );
}

