"use client";

import { useEffect, useRef, useState, HTMLAttributes } from "react";
import { cn } from "@/lib/utils";

const W = 360;
const H = 350;
const CW = 196;
const CH = 246;
const STEP_X = 34;
const STEP_Y = 26;
const STEP_Z = 70;

interface Card {
  id: string;
  title: string;
  src: string;
}

const CARDS: Card[] = [
  { id: "mount", title: "Mountain", src: "https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=400&q=80" },
  { id: "bloom", title: "Bloom", src: "https://images.unsplash.com/photo-1490750967868-88aa4486c946?w=400&q=80" },
  { id: "peak", title: "Peak", src: "https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=400&q=80" },
  { id: "wings", title: "Wings", src: "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=400&q=80" },
];

const slot = (k: number) =>
  `translate3d(${k * STEP_X}px, ${-k * STEP_Y}px, ${-k * STEP_Z}px) skewY(6deg)`;

export interface CardSwapProps extends HTMLAttributes<HTMLDivElement> {
  auto?: boolean;
  every?: number;
}

export function CardSwap({ auto = false, every = 4, className, ...props }: CardSwapProps) {
  const [order, setOrder] = useState(CARDS.map((c) => c.id));
  const els = useRef<Record<string, HTMLDivElement | null>>({});
  const st = useRef({ hover: false, drag: null as null | { id: string; real: boolean; pid: number; x: number; y: number; dx: number; dy: number; t: number } });

  const settle = () => {
    for (const el of Object.values(els.current)) if (el) { el.style.transition = ""; el.style.transform = ""; }
  };

  const swap = () => {
    settle();
    setOrder((o) => [...o.slice(1), o[0]]);
  };

  const unhook = useRef(() => {});
  useEffect(() => () => unhook.current(), []);

  const grab = (e: React.PointerEvent<HTMLDivElement>, id: string, front: boolean) => {
    const s = st.current;
    if (s.drag && e.nativeEvent.isTrusted && !s.drag.real) { unhook.current(); s.drag = null; settle(); }
    if (!front || s.drag || e.button !== 0) return;
    const el = e.currentTarget;
    s.drag = { id, real: e.nativeEvent.isTrusted, pid: e.pointerId, x: e.clientX, y: e.clientY, dx: 0, dy: 0, t: performance.now() };
    el.style.transition = "none";
    const rub = (d: number) => 160 * Math.tanh(d / 160);
    const mine = (ev: PointerEvent) => !!s.drag && ev.pointerId === s.drag.pid && ev.isTrusted === s.drag.real;
    const mv = (ev: PointerEvent) => {
      if (!mine(ev) || !s.drag) return;
      const d = s.drag;
      d.dx = ev.clientX - d.x;
      d.dy = ev.clientY - d.y;
      const x = rub(d.dx), y = rub(d.dy);
      el.style.transform = `${slot(0)} translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) rotate(${(x * 0.05).toFixed(2)}deg)`;
    };
    const up = (ev: PointerEvent) => {
      if (!mine(ev) || !s.drag) return;
      const d = s.drag;
      s.drag = null;
      unhook.current();
      const far = Math.hypot(d.dx, d.dy);
      const quick = far / Math.max(1, performance.now() - d.t) > 0.6;
      if (ev.type !== "pointercancel" && (far < 6 || far > 70 || (quick && far > 24))) { swap(); return; }
      settle();
    };
    window.addEventListener("pointermove", mv);
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", up);
    unhook.current = () => {
      window.removeEventListener("pointermove", mv);
      window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", up);
      unhook.current = () => {};
    };
  };

  useEffect(() => {
    if (!auto) return;
    const id = window.setInterval(() => {
      if (!st.current.hover && !st.current.drag && !document.hidden) swap();
    }, Math.max(1.5, every) * 1000);
    return () => window.clearInterval(id);
  }, [auto, every, order]);

  return (
    <div
      className={cn("csw", className)}
      style={{ width: W, height: H }}
      onPointerEnter={() => { st.current.hover = true; }}
      onPointerLeave={() => { st.current.hover = false; }}
      {...props}
    >
      <div className="csw-stage" style={{ width: CW, height: CH }}>
        {CARDS.map((c) => {
          const k = order.indexOf(c.id);
          const front = k === 0;
          return (
            <div
              key={c.id}
              ref={(el) => { els.current[c.id] = el; }}
              className="csw-card"
              data-front={front || undefined}
              style={{ zIndex: CARDS.length - k, ["--t" as string]: slot(k) } as React.CSSProperties}
              onPointerDown={(e) => grab(e, c.id, front)}
            >
              <img className="csw-photo" src={c.src} alt={c.title} draggable={false} />
              <div className="csw-tag">{c.title}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

